variables.result:
{# Shared build-time source embedded into the two pure HA script templates. #}
{% macro color_json(color) -%}
  {{- ({'kelvin':color.kelvin} if 'kelvin' in color else {'rgb':color.rgb|list})|to_json -}}
{%- endmacro %}

{% macro rgb_value(color) -%}
  {%- if 'rgb' in color -%}
    {{- color.rgb|list|to_json -}}
  {%- else -%}
    {%- set t = color.kelvin / 100 -%}
    {%- set r = 255 if t <= 66 else 329.698727446 * ((t-60) ** -0.1332047592) -%}
    {%- set g = 99.4708025861 * (t|log) - 161.1195681661 if t <= 66 else 288.1221695283 * ((t-60) ** -0.0755148492) -%}
    {%- set b = 255 if t >= 66 else 0 if t <= 19 else 138.5177312231 * ((t-10)|log) - 305.0447927307 -%}
    {{- [[0,[255,r]|min]|max|round|int, [0,[255,g]|min]|max|round|int, [0,[255,b]|min]|max|round|int]|to_json -}}
  {%- endif -%}
{%- endmacro %}

{% macro mix_color(a, b, amount) -%}
  {%- if amount <= 0 -%}{{- color_json(a) -}}
  {%- elif amount >= 1 -%}{{- color_json(b) -}}
  {%- elif 'kelvin' in a and 'kelvin' in b -%}
    {{- {'kelvin': a.kelvin + (b.kelvin-a.kelvin)*amount}|to_json -}}
  {%- else -%}
    {%- set left=rgb_value(a)|from_json -%}
    {%- set right=rgb_value(b)|from_json -%}
    {{- {'rgb': [(left[0]+(right[0]-left[0])*amount)|round|int, (left[1]+(right[1]-left[1])*amount)|round|int, (left[2]+(right[2]-left[2])*amount)|round|int]}|to_json -}}
  {%- endif -%}
{%- endmacro %}

{% macro scale_value(day, cosy, position, warm_end) -%}
  {%- set p = [-2,[2,position]|min]|max -%}
  {%- if p == 0 -%}
    {%- set brightness=cosy.brightness -%}{%- set color=cosy.color -%}
  {%- elif p == 1 -%}
    {%- set brightness=day.brightness -%}{%- set color=day.color -%}
  {%- elif p > 1 -%}
    {%- set brightness=day.brightness+(255-day.brightness)*(p-1) -%}
    {%- set color=mix_color(day.color, {'kelvin':6500}, p-1)|from_json -%}
  {%- elif p > 0 -%}
    {%- set brightness=cosy.brightness+(day.brightness-cosy.brightness)*p -%}
    {%- set color=mix_color(cosy.color,day.color,p)|from_json -%}
  {%- else -%}
    {# Preserve configured anchors below the normal floor; moving down must never brighten them. #}
    {%- set floor=[76.5,cosy.brightness]|min -%}
    {%- set slope=[0,day.brightness-cosy.brightness,(cosy.brightness-floor)/2]|max -%}
    {%- set brightness=[floor,cosy.brightness+p*slope]|max -%}
    {%- if p <= -1 -%}
      {%- set color=mix_color({'rgb':[255,134,7]}, {'rgb':warm_end}, -p-1)|from_json -%}
    {%- elif 'kelvin' in cosy.color and cosy.color.kelvin >= 1950 -%}
      {%- set color={'kelvin':cosy.color.kelvin+(1950-cosy.color.kelvin)*(-p)} -%}
    {%- else -%}
      {%- set color=mix_color(cosy.color, {'rgb':[255,134,7]}, -p)|from_json -%}
    {%- endif -%}
  {%- endif -%}
  {{- {'brightness':[0,[255,brightness]|min]|max, 'color':color_json(color)|from_json, 'position':p}|to_json -}}
{%- endmacro %}

{# Compile only on anchor changes. Sampling retains the original arithmetic order. #}
{% macro gradient_signature(day,cosy,warm_end) -%}
 {{- [1,day.brightness,color_json(day.color)|from_json,cosy.brightness,color_json(cosy.color)|from_json,warm_end|list]|to_json -}}
{%- endmacro %}

{% macro gradient_color(left,right) -%}
 {%- set a=color_json(left)|from_json -%}{%- set b=color_json(right)|from_json -%}
 {%- if 'kelvin' in a and 'kelvin' in b -%}
  {{- {'left':a,'right':b,'kind':'kelvin','start':a.kelvin,'delta':b.kelvin-a.kelvin}|to_json -}}
 {%- else -%}
  {%- set x=rgb_value(a)|from_json -%}{%- set y=rgb_value(b)|from_json -%}
  {{- {'left':a,'right':b,'kind':'rgb','start':x,'delta':[y[0]-x[0],y[1]-x[1],y[2]-x[2]]}|to_json -}}
 {%- endif -%}
{%- endmacro %}

{% macro gradient_compile(day,cosy,warm_end) -%}
 {%- set floor=[76.5,cosy.brightness]|min -%}
 {%- set crossover={'rgb':[255,134,7]} -%}
 {%- set lower={'kelvin':1950} if 'kelvin' in cosy.color and cosy.color.kelvin>=1950 else crossover -%}
 {{- {'version':1,
       'day':{'brightness':day.brightness,'color':color_json(day.color)|from_json},
       'cosy':{'brightness':cosy.brightness,'color':color_json(cosy.color)|from_json},
       'brightness':{'floor':floor,'lower':[0,day.brightness-cosy.brightness,(cosy.brightness-floor)/2]|max,'middle':day.brightness-cosy.brightness,'upper':255-day.brightness},
       'colors':{'lower':gradient_color(cosy.color,lower)|from_json,'middle':gradient_color(cosy.color,day.color)|from_json,'upper':gradient_color(day.color,{'kelvin':6500})|from_json,'tail':gradient_color(crossover,{'rgb':warm_end})|from_json}}|to_json -}}
{%- endmacro %}

{% macro gradient_color_valid(color) -%}
 {%- set n=namespace(ok=color is mapping) -%}
 {%- if n.ok -%}
  {%- if 'kelvin' in color and 'rgb' not in color -%}
   {%- set n.ok=color.kelvin is number and color.kelvin is not boolean and 0<color.kelvin<1e20 -%}
  {%- elif 'rgb' in color and 'kelvin' not in color and color.rgb is sequence and color.rgb is not string and color.rgb is not mapping and color.rgb|count==3 -%}
   {%- for v in color.rgb -%}{%- if v is not number or v is boolean or not (0<=v<=255) -%}{%- set n.ok=false -%}{%- endif -%}{%- endfor -%}
  {%- else -%}{%- set n.ok=false -%}{%- endif -%}
 {%- endif -%}
 {{- n.ok|to_json -}}
{%- endmacro %}

{% macro gradient_valid(entry,signature) -%}
 {# Cache is our own compiled data: validate version, anchor identity and complete shape.
    Never recompute Kelvin conversions to validate a cache hit. #}
 {%- set n=namespace(ok=entry is mapping) -%}
 {%- if n.ok -%}{%- set n.ok=entry.get('signature')==signature and entry.get('curve') is mapping -%}{%- endif -%}
 {%- if n.ok -%}
  {%- set c=entry.curve -%}
  {%- set n.ok=c.get('version')==1 and c.get('day') is mapping and c.get('cosy') is mapping and c.get('brightness') is mapping and c.get('colors') is mapping -%}
  {%- if n.ok -%}
   {%- set n.ok=c.day.get('brightness')==signature[1] and c.day.get('color')==signature[2] and c.cosy.get('brightness')==signature[3] and c.cosy.get('color')==signature[4] -%}
   {%- for name in ['floor','lower','middle','upper'] -%}
    {%- set v=c.brightness.get(name) -%}{%- if v is not number or v is boolean or not (-1e20<v<1e20) -%}{%- set n.ok=false -%}{%- endif -%}
   {%- endfor -%}
   {%- for name in ['lower','middle','upper','tail'] -%}
    {%- set piece=c.colors.get(name) -%}
    {%- if piece is not mapping -%}{%- set n.ok=false -%}
    {%- else -%}
     {%- if not (gradient_color_valid(piece.get('left'))|from_json) or not (gradient_color_valid(piece.get('right'))|from_json) -%}{%- set n.ok=false -%}{%- endif -%}
     {%- if piece.get('kind')=='kelvin' -%}
      {%- for field in ['start','delta'] -%}{%- set v=piece.get(field) -%}{%- if v is not number or v is boolean or not (-1e20<v<1e20) -%}{%- set n.ok=false -%}{%- endif -%}{%- endfor -%}
     {%- elif piece.get('kind')=='rgb' -%}
      {%- for field in ['start','delta'] -%}
       {%- set values=piece.get(field) -%}
       {%- if values is not sequence or values is string or values is mapping or values|count!=3 -%}{%- set n.ok=false -%}
       {%- else -%}{%- for v in values -%}{%- if v is not number or v is boolean or not (-1e20<v<1e20) -%}{%- set n.ok=false -%}{%- endif -%}{%- endfor -%}{%- endif -%}
      {%- endfor -%}
     {%- else -%}{%- set n.ok=false -%}{%- endif -%}
    {%- endif -%}
   {%- endfor -%}
  {%- endif -%}
 {%- endif -%}
 {{- n.ok|to_json -}}
{%- endmacro %}

{% macro gradient_color_sample(piece,amount) -%}
 {%- if amount<=0 -%}{{- piece.left|to_json -}}
 {%- elif amount>=1 -%}{{- piece.right|to_json -}}
 {%- elif piece.kind=='kelvin' -%}{{- {'kelvin':piece.start+piece.delta*amount}|to_json -}}
 {%- else -%}{{- {'rgb':[(piece.start[0]+piece.delta[0]*amount)|round|int,(piece.start[1]+piece.delta[1]*amount)|round|int,(piece.start[2]+piece.delta[2]*amount)|round|int]}|to_json -}}
 {%- endif -%}
{%- endmacro %}

{% macro gradient_sample(curve,position) -%}
 {%- set p=[-2,[2,position]|min]|max -%}
 {%- if p==0 -%}{%- set brightness=curve.cosy.brightness -%}{%- set color=curve.cosy.color -%}
 {%- elif p==1 -%}{%- set brightness=curve.day.brightness -%}{%- set color=curve.day.color -%}
 {%- elif p>1 -%}
  {%- set brightness=curve.day.brightness+curve.brightness.upper*(p-1) -%}
  {%- set color=gradient_color_sample(curve.colors.upper,p-1)|from_json -%}
 {%- elif p>0 -%}
  {%- set brightness=curve.cosy.brightness+curve.brightness.middle*p -%}
  {%- set color=gradient_color_sample(curve.colors.middle,p)|from_json -%}
 {%- else -%}
  {%- set brightness=[curve.brightness.floor,curve.cosy.brightness+p*curve.brightness.lower]|max -%}
  {%- set color=gradient_color_sample(curve.colors.tail,-p-1)|from_json if p<=-1 else gradient_color_sample(curve.colors.lower,-p)|from_json -%}
 {%- endif -%}
 {{- {'brightness':[0,[255,brightness]|min]|max,'color':color,'position':p}|to_json -}}
{%- endmacro %}

{# One logical input stream per room; each source keeps a bounded snapshot.
   The most recent snapshot includes preceding inputs from the room's other
   remotes, so alternating devices cannot drop or apply a click twice. #}
{% macro latest_remote_key(records,room) -%}
 {% set pick=namespace(key='',stamp=-1) %}
 {% for key,r in records|dictsort if r is mapping and r.get('scope')=='room' and r.get('target')==room and (r.get('kind')=='input' or (r.get('kind')=='channels' and r.get('via')=='remote')) %}
  {% set stamp=as_timestamp(r.get('when'),0) %}
  {% if stamp>=pick.stamp %}{% set pick.key=key %}{% set pick.stamp=stamp %}{% endif %}
 {% endfor %}
 {{- pick.key|to_json -}}
{%- endmacro %}

{# Pure Normal Light processor. The adapter stores ticks; only this processor knows
   how ticks map to the Day/Cosy gradient. Animation processors default to no-op. #}
{% macro normal_position(input, item, level) -%}
 {% set d=item.day.brightness-item.cosy.brightness %}
 {% set floor=[76.5,item.cosy.brightness]|min %}
 {% set slope=[0,d,(item.cosy.brightness-floor)/2]|max %}
 {% if input.get('anchor')=='day' %}{% set seed=1 %}
 {% elif input.get('anchor')=='cosy' %}{% set seed=0 %}
 {% elif input.get('legacy_position') is number %}{% set seed=input.legacy_position %}
 {% elif level>item.day.brightness and item.day.brightness<255 %}{% set seed=1+(level-item.day.brightness)/(255-item.day.brightness) %}
 {% elif level<item.cosy.brightness and slope>0 %}{% set seed=[-2,(level-item.cosy.brightness)/slope]|max %}
 {% else %}{% set seed=(level-item.cosy.brightness)/d if d>0 else 1 %}{% endif %}
 {{- ([input.lower,[input.upper,seed*10+input.steps]|min]|max/10)|to_json -}}
{%- endmacro %}

{% macro input_claims(value,key,stamp) -%}
 {% set n=namespace(claims=[]) %}
 {% if value.get('selection') not in ['day','cosy',none] and value.get('legacy_channels') is not mapping %}
  {% if value.get('selection_input') is mapping %}
   {% set n.claims=n.claims+[{'kind':'input','input':dict(value.selection_input,step_range=value.get('step_range',{'min':-20,'max':20}),anchor=(value.get('period') if value.selection_input.get('anchor') in ['day','cosy'] and value.get('period') in ['day','cosy'] else value.selection_input.get('anchor','current'))),'updated':value.selection_input.get('updated',stamp)}] %}
  {% endif %}
  {% set n.claims=n.claims+[{'kind':'effect','effect':value.selection,'instance':value.get('selection_instance',key~':'~value.selection),'updated':value.get('selection_updated',stamp)}] %}
 {% endif %}
 {% if value.get('adjustment') is mapping and (value.get('selection') in ['day','cosy',none] or value.get('adjustment')!=value.get('selection_input')) %}
  {% set n.claims=n.claims+[{'kind':'input','input':dict(value.adjustment,step_range=value.get('step_range',{'min':-20,'max':20}),anchor=(value.get('period') if value.adjustment.get('anchor') in ['day','cosy'] and value.get('period') in ['day','cosy'] else value.adjustment.get('anchor','current'))),'updated':value.adjustment.get('updated',stamp)}] %}
 {% endif %}
 {{- n.claims|to_json -}}
{%- endmacro %}

{# No time, state, service or event access. Only record timestamps are interpreted. #}
{% macro valid_color(c) -%}
  {%- set v=namespace(ok=false) -%}
  {%- if c is mapping -%}
    {%- if 'kelvin' in c and 'rgb' not in c and c.kelvin is number and c.kelvin is not boolean and c.kelvin >= 1000 and c.kelvin <= 10000 -%}
      {%- set v.ok=true -%}
    {%- elif 'rgb' in c and 'kelvin' not in c and c.rgb is sequence and c.rgb is not string and c.rgb is not mapping and c.rgb|count == 3 -%}
      {%- set v.ok=true -%}
      {%- for component in c.rgb -%}
        {%- if component is not number or component is boolean or component < 0 or component > 255 or component != component -%}{%- set v.ok=false -%}{%- endif -%}
      {%- endfor -%}
    {%- endif -%}
  {%- endif -%}
  {{- v.ok|to_json -}}
{%- endmacro %}

{% macro effect_channels(name) -%}
  {%- set d=catalog.effects.get(name,{}) if name is string else {} -%}
  {%- set channels=d.get('channels',[]) if d is mapping else [] -%}
  {%- set v=namespace(ok=channels is sequence and channels is not string and channels is not mapping and channels|count > 0) -%}
  {%- if v.ok -%}
    {%- for channel in channels -%}{%- if channel not in ['brightness','color'] -%}{%- set v.ok=false -%}{%- endif -%}{%- endfor -%}
  {%- endif -%}
  {{- (channels|list if v.ok else [])|to_json -}}
{%- endmacro %}


{% set out=namespace(targets={},assignments={},inputs={},streams={},order=[]) %}
{% for target,item in base|dictsort if item.get('is_room',false) %}{% set out.order=out.order+[target] %}{% endfor %}
{% for target,item in base|dictsort if not item.get('is_room',false) %}{% set out.order=out.order+[target] %}{% endfor %}
{% for target in out.order %}{% set item=base[target] %}


{% set area=item.area %}
{% if area not in out.streams %}{% set out.streams=dict(out.streams,**{area:latest_remote_key(overrides,area)|from_json}) %}{% endif %}

  {% set is_room=item.get('is_room',false) %}
  {% set ignored=item.get('ignore_overrides',[]) %}
  {% set ignored=ignored if ignored is sequence and ignored is not string and ignored is not mapping else [] %}
  {% set observed=item.get('observed',{}) %}
  {% set observed=observed if observed is mapping else {} %}
  {% set n=namespace(candidates={'brightness':[],'color':[]},sources={},owners={},underlying={}) %}
  {% set gradient=namespace(checked=false,curve=none,samples={}) %}
  {% for key,record in overrides|dictsort if record is mapping and key not in ignored %}
    {% set value=record.get('value') %}
    {% set scope=record.get('scope','lamp' if record.get('kind') == 'light' else '') %}
    {% set applies=(scope == 'house' and record.get('target') == 'house' and area not in private) or (scope == 'room' and record.get('target') == area) or (scope == 'lamp' and not is_room and record.get('target') == target) %}

{% if record.get('scope')=='room' and (record.get('kind')=='input' or (record.get('kind')=='channels' and record.get('via')=='remote')) and key!=out.streams.get(area) %}{% set applies=false %}{% endif %}
{% if applies %}

      {% set stamp=as_timestamp(record.get('when'),0)|float(0) %}
      {% set patch={} %}

{% if record.get('kind') == 'input' and value is mapping %}
 {% set patch=value.get('legacy_channels',{}) %}
 {% for claim in input_claims(value,key,stamp)|from_json %}
  {% for channel in ['brightness','color'] if claim.kind=='input' or channel in effect_channels(claim.get('effect'))|from_json %}
   {% set n.candidates=dict(n.candidates,**{channel:n.candidates[channel]+[{'key':key,'updated':claim.updated,'source':claim,'baseline_only':false}]}) %}
  {% endfor %}
 {% endfor %}
{% elif record.get('kind') == 'channels' and value is mapping and value.get('channels') is mapping %}

        {% set patch=value.channels %}
      {% elif record.get('kind') == 'light' %}
        {% if value is none %}
          {% set patch={'brightness':{'kind':'constant','value':observed.get('brightness',item.brightness)},'color':{'kind':'constant','value':observed.get('color',item.color)}} %}
        {% elif value is mapping %}
          {% set ef=value.get('effect') %}
          {% set declared=effect_channels(ef)|from_json %}
          {% if ef is not none and ef != 'Normal light' %}
            {% set legacy=namespace(p={}) %}
            {% for channel in declared %}
              {% set source={'kind':'effect','effect':ef,'instance':key} %}
              {% if 'brightness' in value %}{% set source=dict(source,intensity=value.brightness) %}{% endif %}
              {% set legacy.p=dict(legacy.p,**{channel:source}) %}
            {% endfor %}
            {% if declared|count == 0 %}
              {% set legacy.p={'brightness':{'kind':'constant','value':item.brightness},'color':{'kind':'constant','value':item.color}} %}
            {% elif 'brightness' in value and 'brightness' not in declared %}
              {% set legacy.p=dict(legacy.p,brightness={'kind':'constant','value':value.brightness}) %}
            {% endif %}
            {% set patch=legacy.p %}
          {% elif ef == 'Normal light' %}
            {% set patch={'brightness':{'kind':'constant','value':value.get('brightness',observed.get('brightness',item.brightness))},'color':{'kind':'constant','value':observed.get('color',item.color)}} %}
          {% elif 'brightness' in value %}
            {% set patch={'brightness':{'kind':'constant','value':value.brightness}} %}
          {% endif %}
        {% endif %}
      {% endif %}
      {% for channel in ['brightness','color'] if channel in patch %}

{% set source=patch[channel] %}
{# Read compatibility for remote records written before this deployment. #}
{% if record.get('via')=='remote' and source is mapping and source.get('kind')=='scale' %}
 {% set source={'kind':'input','input':{'steps':0,'lower':-20,'upper':20,'legacy_position':source.position},'updated':source.get('updated',stamp)} %}
{% endif %}

        {% set update=source.get('updated',stamp) if source is mapping else stamp %}
        {% set update=update if update is number and update is not boolean and update > -1e20 and update < 1e20 else stamp %}
        {% set entries=[{'key':key,'updated':update,'source':source,'baseline_only':false}] %}
        {# Replacing a stable source record must retain the constant/scale that fed its effect.
           Its original timestamp competes with other baseline values; selecting an effect
           does not make the carried input newer than unrelated manual settings. #}
        {% if source is mapping and source.get('kind') == 'effect' and channel in effect_channels(source.get('effect'))|from_json and source.get('instance') is string and source.instance|length > 0 %}
          {% set carried=namespace(source=source.get('underlying')) %}
          {% for depth in range(8) %}
            {% if carried.source is mapping and carried.source.get('kind') == 'effect' %}
              {% set carried.source=carried.source.get('underlying') %}
            {% endif %}
          {% endfor %}
          {% if carried.source is mapping and carried.source.get('kind') in ['constant','scale'] %}
            {% set carried_stamp=carried.source.get('updated') %}
            {% if carried_stamp is number and carried_stamp is not boolean and carried_stamp > -1e20 and carried_stamp <= update %}
              {% set entries=entries+[{'key':key,'updated':carried_stamp,'source':carried.source,'baseline_only':true}] %}
            {% endif %}
          {% endif %}
        {% endif %}
        {% set n.candidates=dict(n.candidates,**{channel:n.candidates[channel]+entries}) %}
      {% endfor %}
    {% endif %}
  {% endfor %}
  {% set baseline_effect=item.get('effect','Normal light') %}
  {% set declared=effect_channels(baseline_effect)|from_json %}
  {% set enabled=item.get('effect_channels',declared) %}
  {% set enabled=enabled if enabled is sequence and enabled is not string and enabled is not mapping else [] %}
  {% for channel in ['brightness','color'] %}
    {% set initial= color_json(item[channel])|from_json if channel=='color' else item[channel] %}
    {% set c=namespace(underlying=initial,source={'kind':'constant','value':initial,'updated':-1},owner='base') %}
    {% if channel in declared and channel in enabled %}
      {% set c.source={'kind':'effect','effect':baseline_effect,'instance':item.get('effect_instance','base:' ~ target ~ ':' ~ baseline_effect),'updated':-1} %}
      {% set c.owner='base:' ~ baseline_effect %}
    {% endif %}
    {% for candidate in n.candidates[channel]|sort(attribute='key')|sort(attribute='updated') %}
      {% set source=candidate.source %}
      {% set check=namespace(valid=false,ignore=false,value=initial,selected={}) %}
      {% if source is mapping %}
        {% if source.get('kind') == 'constant' %}
          {% set v=source.get('value') %}
          {% set check.valid=(v is number and v is not boolean and v >= 0 and v <= 255) if channel == 'brightness' else valid_color(v)|from_json %}
          {% if check.valid %}{% set check.value=color_json(v)|from_json if channel=='color' else v %}{% endif %}

{% elif source.get('kind') in ['scale','input'] %}
          {% set p=source.get('position') %}
          {% if source.kind=='input' %}
           {% set input=source.get('input',{}) %}
           {% set valid=namespace(ok=input is mapping and item.get('day') is mapping and item.get('cosy') is mapping) %}
           {% for field in ['steps','lower','upper'] %}
            {% set v=input.get(field) if input is mapping else none %}
            {% if v is not number or v is boolean or v!=v or v < -40 or v > 40 %}{% set valid.ok=false %}{% endif %}
           {% endfor %}
           {% set bounds=input.get('step_range',{'min':-20,'max':20}) if input is mapping else none %}
           {% if valid.ok and -20<=input.lower<=input.upper<=20 and bounds is mapping and bounds.get('min') is number and bounds.min is not boolean and bounds.get('max') is number and bounds.max is not boolean and -20<=bounds.min<=bounds.max<=20 %}
            {% set input=dict(input,lower=[bounds.min,[bounds.max,input.lower]|min]|max,upper=[bounds.min,[bounds.max,input.upper]|min]|max) %}
            {% set ref=candidate.key~':'~candidate.updated %}
            {% set position=out.inputs.get(ref) %}
            {% if position is none %}
             {% set level=c.underlying if channel=='brightness' else n.underlying.get('brightness',item.brightness) %}
             {% set position={'position':normal_position(input,item,level)|from_json,'level':level} %}
             {% if is_room %}{% set out.inputs=dict(out.inputs,**{ref:position}) %}{% endif %}
            {% endif %}
            {% set p=position.position %}
            {% set processor=c.source.effect if c.source.kind=='effect' else 'Normal light' %}
            {% set strategy=catalog.get('processors',{}).get(processor,{}).get('remote_adjustment','gradient' if processor=='Normal light' else 'ignore') %}
            {% set check.ignore=strategy!='gradient' %}
           {% else %}{% set check.ignore=true %}{% endif %}
          {% endif %}

          {% if not check.ignore and p is number and p is not boolean and p > -1e20 and p < 1e20 and item.get('day') is mapping and item.get('cosy') is mapping %}
            {% if not gradient.checked %}
              {% set cached=(gradients|default({})).get(target) if gradients|default({}) is mapping else none %}
              {% set signature=gradient_signature(item.day,item.cosy,warm_end)|from_json %}
